import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第三十五卦 晉 火地晉 離上坤下","description":"周易 - 第三十五卦 晉 火地晉 離上坤下","frontmatter":{"title":"第三十五卦 晉 火地晉 離上坤下","description":"周易 - 第三十五卦 晉 火地晉 離上坤下"},"headers":[],"relativePath":"classics/zhouyi/036.md","filePath":"classics/zhouyi/036.md"}'),l={name:"classics/zhouyi/036.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="晉" tabindex="-1">晉 <a class="header-anchor" href="#晉" aria-label="Permalink to “晉”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>康侯用錫馬蕃庶，晝日三接。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>晉，進也。明出地上，順而麗乎大明，柔進而上行。是以康侯用錫馬蕃庶，晝日三接也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>明出地上，晉；君子以自昭明德。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>晉如，摧如，貞吉。罔孚，裕無咎。象 曰：晉如，摧如；獨行正也。裕無咎；未受命也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>晉如，愁如，貞吉。受茲介福，於其王母。象曰：受之介福，以中正也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>眾允，悔亡。象曰：眾允之，志上行也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>晉如碩鼠，貞厲。象曰：碩鼠貞厲，位不當也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>悔亡，失得勿恤，往吉無不利。象曰：失得勿恤，往有慶也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>晉其角，維用伐邑，厲吉無咎，貞吝。象曰：維用伐邑，道未光也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
